from labels import normalize_label
from durations import duration_label
separators = "\t\n\r\v\f\u0085\u00a0\u1680\u2000\u2007\u2028\u2029\u202f\u205f\u3000"
for separator in separators:
    assert normalize_label(separator + "Straße" + separator + separator + "Σ" + separator) == "strasse σ"
def expect_value_error(function, value):
    try:
        function(value)
    except ValueError:
        return
    raise AssertionError("invalid input was accepted")
for bad in (separators, False, b"x", [], {}):
    expect_value_error(normalize_label, bad)
for seconds, expected in ((59, "0m59s"), (60, "1m00s"), (3601, "60m01s")):
    assert duration_label(seconds) == expected
expect_value_error(duration_label, False)
print("Unicode label and duration boundary checks passed")
